DIR = {'N': Direction.UP, 'S': Direction.DOWN, 'E': Direction.RIGHT, 'W': Direction.LEFT}
def ok_drop(e, x, y, d):
    dp = e.drop_position
    if d == 'N': return dp.y < y
    if d == 'S': return dp.y > y
    if d == 'E': return dp.x > x
    return dp.x < x
def ins(x, y, d):
    try:
        go(x, y)
        e = place_entity(Prototype.Inserter, direction=DIR[d], position=Position(x=x, y=y))
        if not ok_drop(e, x, y, d):
            e = rotate_entity(e, OPP[d])
        print('ins', e.position, 'pick', e.pickup_position, 'drop', e.drop_position)
        return e
    except Exception as ex:
        errs.append(('ins', x, y, str(ex)[:200]))
